import json
import numpy as np
import jax
import jax.numpy as jnp


def load_input(path):
    if path.endswith(".npy"):
        return np.load(path)
    if path.endswith(".npz"):
        return dict(np.load(path))
    raise ValueError(f"Unsupported input format: {path}")


def save_output(path, array):
    np.save(path, np.asarray(array))


def compute_task(task):
    task_id = task["id"]
    data = load_input(task["input"])

    if task_id == "basic_reduce":
        x = jnp.array(data)
        return jnp.mean(x, axis=1)

    if task_id == "map_square":
        x = jnp.array(data)
        return jnp.square(x)

    if task_id == "grad_logistic":
        x = jnp.array(data["x"])
        y = jnp.array(data["y"])
        w = jnp.array(data["w"])

        def loss_fn(w_vec, x_mat, y_vec):
            logits = x_mat @ w_vec
            return jnp.mean(jnp.logaddexp(0.0, -y_vec * logits))

        grad_fn = jax.grad(loss_fn)
        return grad_fn(w, x, y)

    if task_id == "scan_rnn":
        seq = jnp.array(data["seq"])
        h0 = jnp.array(data["init"])
        wx = jnp.array(data["Wx"])
        wh = jnp.array(data["Wh"])
        b = jnp.array(data["b"])

        def step(h, x_t):
            h_new = jnp.tanh(x_t @ wx + h @ wh + b)
            return h_new, h_new

        _, hs = jax.lax.scan(step, h0, seq)
        return hs

    if task_id == "jit_mlp":
        x = jnp.array(data["X"])
        w1 = jnp.array(data["W1"])
        b1 = jnp.array(data["b1"])
        w2 = jnp.array(data["W2"])
        b2 = jnp.array(data["b2"])

        def mlp(x_in, w1_in, b1_in, w2_in, b2_in):
            hidden = jnp.maximum(0, x_in @ w1_in + b1_in)
            return hidden @ w2_in + b2_in

        mlp_jit = jax.jit(mlp)
        return mlp_jit(x, w1, b1, w2, b2)

    raise ValueError(f"Unknown task id: {task_id}")


def main():
    with open("problem.json", "r", encoding="utf-8") as handle:
        tasks = json.load(handle)
    for task in tasks:
        output = compute_task(task)
        save_output(task["output"], output)


if __name__ == "__main__":
    main()
